#!/usr/bin/env python3
"""Generated files: every file a program writes says so, naming its generator and its source, and
one check keeps that true (the guidance note `generated-files-are-marked`, which owns the rule).

- **The marker** (`line`, `marker_at`, `mark`): `Code generated by <generator> from <source>. DO NOT
  EDIT.`, in the file's comment syntax (`SYNTAXES`, one regular expression each, `PATTERNS`), as its
  first line; where the format fixes its own first line (`#!`, `<?xml`, Markdown front matter), the
  line right after it. A format without comments (JSON, plain text) is marked in `.gitattributes`
  instead: `<path> linguist-generated generated-by=<generator>`, the generator's spaces written `:`
  as an attribute's value holds none (`attribute`).
- **The declarations** (`load`): `generated.yaml` at the checkout's root lists each generator, its
  source and the tracked paths it writes (`outputs`, globs: `*` within a folder, `**` across), and
  how a fresh run is compared: `check`, a command that fails where a fresh run does not reproduce
  its outputs byte for byte; `held_by`, the test or workflow that reruns it; or `unchecked`, why no
  fresh run can be compared. Exactly one of the three.
- **The lock files** (`LOCKS`): third-party lock files, by name, with the tool that writes them,
  are exempt from the marker; a single line a program edits in a hand-written file (a release's
  version line) is no generated file and is declared nowhere.
- **The check** (`findings`): a declared output that lacks its marker or names another generator, a
  marked file no declaration of the generator it names covers, a declaration that matches no
  tracked file, and a fresh run that differs, each naming the file and the remedy.
- **The notice** (`notice`): what an editor shows on a generated file, `generated by <generator>
  from <source>; edit <source>`.

`generated.py check [--root DIR] [--no-rerun]` runs the check on the tracked files (a folder that
is no git checkout, such as the commit hook's copy of the staged tree, on every file in it);
`--no-rerun` leaves out the fresh runs, as the commit hook does. `generated.py notice PATH` prints a
file's notice. Exit code 0 passed (or the notice printed), 1 findings (or the file is not
generated), 2 a declaration that cannot be read.
"""

from __future__ import annotations

import argparse
import re
import subprocess
import sys
from dataclasses import dataclass
from pathlib import Path, PurePosixPath

sys.path.insert(0, str(Path(__file__).resolve().parent))

ROOT = Path(__file__).resolve().parents[1]
DECLARATIONS = "generated.yaml"
ATTRIBUTES = ".gitattributes"
ATTRIBUTE = "generated-by"
LINGUIST = "linguist-generated"

# Each comment syntax: what opens and what closes a comment line.
SYNTAXES = {
    "hash": ("# ", ""),
    "slash": ("// ", ""),
    "html": ("<!-- ", " -->"),
}
# The comment syntax of each extension; a file without one but with a `#!` line is `hash`. Every
# other format has no comment syntax the check knows, and `.gitattributes` marks it.
EXTENSIONS = {
    ".toml": "hash", ".yaml": "hash", ".yml": "hash", ".sh": "hash", ".ps1": "hash", ".py": "hash",
    ".conf": "hash", ".lock": "hash", ".ini": "hash", ".cfg": "hash",
    ".go": "slash", ".js": "slash", ".ts": "slash",
    ".md": "html", ".html": "html", ".xml": "html",
}
WORDING = "Code generated by {generator} from {source}. DO NOT EDIT."
PATTERNS = {
    name: re.compile("^" + re.escape(opening) + r"Code generated by (?P<generator>\S(?:.*?\S)?) from "
                     r"(?P<source>\S(?:.*?\S)?)\. DO NOT EDIT\." + re.escape(closing) + "$")
    for name, (opening, closing) in SYNTAXES.items()
}

# Third-party lock files, by name, with the tool that writes each: exempt from the marker.
LOCKS = {
    "uv.lock": "uv",
    "go.sum": "go",
    "go.work.sum": "go",
    "package-lock.json": "npm",
    "pnpm-lock.yaml": "pnpm",
    "yarn.lock": "yarn",
    "Cargo.lock": "cargo",
}

# How long a fresh run may take before the check names it as hung.
RERUN_SECONDS = 300


class DeclarationError(Exception):
    """`generated.yaml` cannot be read, naming where and why."""


@dataclass(frozen=True)
class Marker:
    """What a file's marker says: its generator and its source."""

    generator: str
    source: str


@dataclass(frozen=True)
class Generator:
    """One generator as `generated.yaml` declares it."""

    generator: str
    source: str
    outputs: tuple[str, ...]
    check: tuple[str, ...] = ()
    held_by: str = ""
    unchecked: str = ""


# The marker.


def line(generator: str, source: str, syntax: str) -> str:
    """The marker line, without its line end, in `syntax`'s comment."""
    opening, closing = SYNTAXES[syntax]
    return opening + WORDING.format(generator=generator, source=source) + closing


def attribute(generator: str) -> str:
    """The generator as `.gitattributes`' `generated-by` value: spaces written `:`."""
    return generator.replace(" ", ":")


def syntax_of(path: str, text: str = "") -> str | None:
    """The comment syntax of the file at `path`, None where it has none the check knows."""
    found = EXTENSIONS.get(PurePosixPath(path).suffix.lower())
    if found is None and not PurePosixPath(path).suffix and text.startswith("#!"):
        return "hash"
    return found


def _lines(text: str) -> list[str]:
    return text.replace("\r\n", "\n").split("\n")


def place(text: str, syntax: str) -> int:
    """The index of the line the marker stands on: 0, or the line after a first line the format
    fixes (`#!`, `<?xml`, Markdown front matter)."""
    lines = _lines(text)
    if lines and (lines[0].startswith("#!") or lines[0].startswith("<?xml")):
        return 1
    if syntax == "html" and lines and lines[0] == "---":
        for index in range(1, len(lines)):
            if lines[index] == "---":
                return index + 1
    return 0


def marker_at(text: str, syntax: str) -> Marker | None:
    """The marker of `text` where it stands at its place, else None."""
    lines = _lines(text)
    at = place(text, syntax)
    found = PATTERNS[syntax].match(lines[at]) if at < len(lines) else None
    return Marker(found["generator"], found["source"]) if found else None


def mark(text: str, generator: str, source: str, syntax: str) -> str:
    """`text` with its marker at its place; an earlier marker there is replaced."""
    lines = text.split("\n")
    at = place(text, syntax)
    if marker_at(text, syntax) is not None:
        del lines[at]
    lines.insert(at, line(generator, source, syntax))
    return "\n".join(lines)


# The declarations.


def glob(pattern: str) -> re.Pattern[str]:
    """A path glob as a regular expression: `**` across folders, `*` and `?` within one."""
    out, index = [], 0
    while index < len(pattern):
        if pattern.startswith("**/", index):
            out.append("(?:.*/)?")
            index += 3
        elif pattern.startswith("**", index):
            out.append(".*")
            index += 2
        elif pattern[index] == "*":
            out.append("[^/]*")
            index += 1
        elif pattern[index] == "?":
            out.append("[^/]")
            index += 1
        else:
            out.append(re.escape(pattern[index]))
            index += 1
    return re.compile("^" + "".join(out) + "$")


def _front_data():
    """templates.front_data, the YAML subset SE's own data files are read in."""
    import templates

    return templates.front_data, templates.TemplateError


def load(root: Path) -> list[Generator]:
    """The generators `generated.yaml` under `root` declares; none where it has no such file."""
    path = root / DECLARATIONS
    if not path.is_file():
        return []
    front_data, error_type = _front_data()
    try:
        data = front_data(path.read_text(encoding="utf-8"), DECLARATIONS, 1)
    except error_type as error:
        raise DeclarationError(str(error)) from error
    entries = data.get("generators")
    if set(data) != {"generators"} or not isinstance(entries, list):
        raise DeclarationError(f"{DECLARATIONS}: one key, `generators`, a list of generators")
    found, seen = [], set()
    for number, entry in enumerate(entries, 1):
        where = f"{DECLARATIONS}: generator {number}"
        if not isinstance(entry, dict):
            raise DeclarationError(f"{where} is no mapping")
        unknown = set(entry) - {"generator", "source", "outputs", "check", "held_by", "unchecked"}
        if unknown:
            raise DeclarationError(f"{where}: unknown keys {sorted(unknown)}")
        name, source, outputs = entry.get("generator"), entry.get("source"), entry.get("outputs")
        if not isinstance(name, str) or not name.strip() or not isinstance(source, str) or not source.strip():
            raise DeclarationError(f"{where}: `generator` and `source` are its words")
        if name in seen:
            raise DeclarationError(f"{where}: {name} is declared twice; declare each generator once")
        seen.add(name)
        if not isinstance(outputs, list) or not outputs or not all(isinstance(o, str) and o for o in outputs):
            raise DeclarationError(f"{where} ({name}): `outputs` is a list of the paths it writes")
        check = entry.get("check", [])
        if not isinstance(check, list) or not all(isinstance(word, str) for word in check):
            raise DeclarationError(f"{where} ({name}): `check` is a command, a list of words")
        ways = [key for key in ("check", "held_by", "unchecked") if entry.get(key)]
        if len(ways) != 1:
            raise DeclarationError(f"{where} ({name}): name exactly one of `check`, `held_by` and "
                                   "`unchecked`, how a fresh run is compared")
        found.append(Generator(name, source, tuple(outputs), tuple(check), str(entry.get("held_by", "")),
                               str(entry.get("unchecked", ""))))
    return found


def attributes(root: Path) -> list[tuple[re.Pattern[str], dict[str, str], int]]:
    """Each line of `.gitattributes` that sets `linguist-generated` or `generated-by`: its pattern
    (one without a `/` matches a name at any depth, as git's does), its attributes, its line."""
    path = root / ATTRIBUTES
    if not path.is_file():
        return []
    found = []
    for number, text in enumerate(path.read_text(encoding="utf-8").splitlines(), 1):
        words = text.split()
        if not words or words[0].startswith("#"):
            continue
        values = {}
        for word in words[1:]:
            key, _, value = word.partition("=")
            values[key] = value or ("unset" if key.startswith("-") else "set")
        if LINGUIST in values or ATTRIBUTE in values:
            pattern = words[0].lstrip("/") if "/" in words[0] else "**/" + words[0]
            found.append((glob(pattern), values, number))
    return found


def attributes_of(path: str, lines: list[tuple[re.Pattern[str], dict[str, str], int]]) -> dict[str, str]:
    """The generated attributes `.gitattributes` gives `path`, the last line that matches winning."""
    given: dict[str, str] = {}
    for pattern, values, _ in lines:
        if pattern.match(path):
            given.update({key: value for key, value in values.items() if key in (LINGUIST, ATTRIBUTE)})
    return given


# The files.


def tracked(root: Path) -> list[str]:
    """The tracked files that stand in `root`, through git's door; in a folder that is no git
    checkout (the commit hook's copy of the staged tree), every file in it."""
    if not (root / ".git").exists():
        return sorted(p.relative_to(root).as_posix() for p in root.rglob("*") if p.is_file())
    import git_door  # only here, so a generator that writes markers needs no more scripts than this

    listed = git_door.run("ls-files", "-z", root=root)
    if listed.returncode != 0:
        raise DeclarationError(f"git ls-files in {root}: {listed.stderr.strip()}")
    return [p for p in listed.stdout.split("\0") if p and (root / p).is_file()]


def read(root: Path, path: str) -> str:
    data = (root / path).read_bytes()
    return "" if b"\0" in data[:8000] else data.decode("utf-8", errors="replace")


# The check.


def _declared(generators: list[Generator], files: list[str]) -> dict[str, list[Generator]]:
    by_file: dict[str, list[Generator]] = {}
    for generator in generators:
        patterns = [glob(output) for output in generator.outputs]
        for path in files:
            if any(pattern.match(path) for pattern in patterns):
                by_file.setdefault(path, []).append(generator)
    return by_file


def _locked(path: str) -> bool:
    return PurePosixPath(path).name in LOCKS


def marker_findings(root: Path, files: list[str], generators: list[Generator]) -> list[str]:
    """Every finding of the markers and the declarations over `files`, without a fresh run."""
    texts = {path: read(root, path) for path in files}
    lines = attributes(root)
    by_file = _declared(generators, files)
    found = []
    for generator in generators:
        for output in generator.outputs:
            pattern = glob(output)
            if not any(pattern.match(path) for path in files):
                found.append(f"{DECLARATIONS}: {generator.generator} declares {output}, which matches no "
                             "tracked file; remove it, or run the generator and commit what it writes")
    for path in files:
        owners = by_file.get(path, [])
        text = texts[path]
        syntax = syntax_of(path, text)
        given = attributes_of(path, lines)
        seen = marker_at(text, syntax) if syntax else None
        if _locked(path):
            if owners:
                found.append(f"{path}: {LOCKS[PurePosixPath(path).name]}'s lock file, exempt from the "
                             f"marker; remove it from {DECLARATIONS}")
            continue
        if len(owners) > 1:
            found.append(f"{path}: declared by {' and '.join(g.generator for g in owners)}; one "
                         f"generator writes a file, so declare it once in {DECLARATIONS}")
            continue
        if owners:
            owner = owners[0]
            if syntax is None:
                want = attribute(owner.generator)
                if given.get(LINGUIST) not in ("set", "true") or given.get(ATTRIBUTE) != want:
                    found.append(f"{path}: generated by {owner.generator}, in a format without "
                                 f"comments, so {ATTRIBUTES} marks it: add `{path} {LINGUIST} "
                                 f"{ATTRIBUTE}={want}` (or a pattern that covers it)")
            elif seen is None:
                found.append(f"{path}: generated by {owner.generator} but lacks its marker "
                             f"`{line(owner.generator, owner.source, syntax)}`; run {owner.generator}, "
                             f"which writes it, and edit {owner.source} instead of the file")
            elif seen.generator != owner.generator:
                found.append(f"{path}: its marker names {seen.generator}, but {DECLARATIONS} declares it "
                             f"{owner.generator}'s output; run {owner.generator}, or declare the file "
                             f"under {seen.generator}")
            continue
        if seen is not None:
            found.append(f"{path}: marked as generated by {seen.generator}, which {DECLARATIONS} does not "
                         f"declare it of; declare it among {seen.generator}'s outputs, or remove the "
                         "marker from a hand-written file")
        elif given.get(ATTRIBUTE):
            found.append(f"{path}: {ATTRIBUTES} marks it as generated by {given[ATTRIBUTE]}, which "
                         f"{DECLARATIONS} does not declare it of; declare it, or remove the attribute")
    for generator in generators:
        if generator.held_by and not (root / generator.held_by).is_file():
            found.append(f"{DECLARATIONS}: {generator.generator} is held by {generator.held_by}, which "
                         "does not exist; name the test or workflow that reruns it")
    return found


def run_check(root: Path, command: tuple[str, ...]) -> tuple[int, str]:
    """Run a declared `check` command in `root`, through the process door: its exit code and its
    output. The door loads here, as a copy of the generator alone (se_plugin.py's) runs no check."""
    import process_door

    try:
        done = process_door.run(list(command), cwd=root, capture_output=True, text=True,
                                timeout=RERUN_SECONDS)
    except (OSError, subprocess.TimeoutExpired) as error:
        return 2, str(error)
    return done.returncode, (done.stdout + done.stderr).strip()


def rerun_findings(root: Path, generators: list[Generator], runner=run_check) -> list[str]:
    """Each generator whose declared `check`, a fresh run compared byte for byte, fails."""
    found = []
    for generator in generators:
        if not generator.check:
            continue
        code, output = runner(root, generator.check)
        if code != 0:
            tail = " | ".join(output.splitlines()[-5:])
            found.append(f"{generator.generator}: a fresh run does not reproduce its outputs "
                         f"(`{' '.join(generator.check)}` exits {code}: {tail}); run "
                         f"{generator.generator} and commit what it writes")
    return found


def findings(root: Path, rerun: bool = True, files: list[str] | None = None, runner=run_check) -> list[str]:
    """Every finding of the check on `root`."""
    generators = load(root)
    files = tracked(root) if files is None else files
    found = marker_findings(root, files, generators)
    if rerun:
        found += rerun_findings(root, generators, runner)
    return found


# The notice.


def notice(root: Path, path: str) -> str | None:
    """What an editor shows on the file at `path` (relative to `root`, slash-separated): `generated
    by <generator> from <source>; edit <source>`, None where it is no generated file."""
    if _locked(path):
        return f"generated by {LOCKS[PurePosixPath(path).name]}; edit what it locks, then run it"
    text = read(root, path) if (root / path).is_file() else ""
    syntax = syntax_of(path, text)
    seen = marker_at(text, syntax) if syntax else None
    if seen is not None:
        return f"generated by {seen.generator} from {seen.source}; edit {seen.source}"
    owners = _declared(load(root), [path]).get(path, [])
    if owners:
        return f"generated by {owners[0].generator} from {owners[0].source}; edit {owners[0].source}"
    return None


def main(argv: list[str] | None = None) -> int:
    parser = argparse.ArgumentParser(prog="generated.py", description=__doc__.splitlines()[0])
    parser.add_argument("--root", type=Path, default=ROOT, help="the checkout (default: SE's own)")
    commands = parser.add_subparsers(dest="command", required=True)
    checking = commands.add_parser("check", help="fail where a generated file is not marked, a marked "
                                   "one is not declared, or a fresh run differs")
    checking.add_argument("--no-rerun", action="store_true", help="leave out the fresh runs")
    noticing = commands.add_parser("notice", help="print what an editor shows on a generated file")
    noticing.add_argument("path", help="the file, relative to the root")
    args = parser.parse_args(argv)
    root = args.root.resolve()
    try:
        if args.command == "notice":
            said = notice(root, PurePosixPath(args.path).as_posix())
            if said is None:
                print(f"generated.py: {args.path} is no generated file", file=sys.stderr)
                return 1
            print(said)
            return 0
        found = findings(root, rerun=not args.no_rerun)
    except DeclarationError as error:
        print(f"generated.py: {error}", file=sys.stderr)
        return 2
    for finding in found:
        print(f"generated.py: {finding}")
    if found:
        print(f"generated.py: {len(found)} finding(s) in {root} (the guidance note "
              "generated-files-are-marked)")
        return 1
    print(f"generated.py: every generated file is marked and declared in {root}"
          + ("" if args.no_rerun else ", and each fresh run reproduces it"))
    return 0


if __name__ == "__main__":
    sys.exit(main())
